def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract sequences once
    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    opp_c = 0
    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'D':
            my_d += 1

    # Current streaks
    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if opp_actions[i] == 'C':
            opp_c_streak += 1
        else:
            break

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if opp_actions[i] == 'D':
            opp_d_streak += 1
        else:
            break

    last_my = my_actions[-1]
    last_opp = opp_actions[-1]

    opp_def_rate = opp_d / float(n)

    # Detect unconditional cooperator: never defected.
    # Exploit worst-case (defect last 3) only after establishing enough cooperation,
    # otherwise keep cooperating. We only need safe exploitation near the end.
    if opp_d == 0:
        rounds_left = 100 - n
        if rounds_left <= 2:
            return 'D'
        return 'C'

    # Sustained defector: if opponent is heavily defecting overall
    if opp_def_rate >= 0.85 and n >= 6:
        # Almost hopeless. Defect, but occasionally test for forgiveness.
        if n % 11 == 0:
            return 'C'
        return 'D'

    # Near endgame: if opponent is mostly cooperative, defect last rounds.
    rounds_left = 100 - n
    if rounds_left <= 2 and opp_def_rate <= 0.3:
        return 'D'

    # Recovery logic: if opponent just cooperated after we defected, reciprocate
    # to break retaliation cycles.
    if last_opp == 'C' and last_my == 'D':
        # If we've been defecting a lot recently, definitely return to C.
        recent_my_d = 0
        for i in range(max(0, n - 4), n):
            if my_actions[i] == 'D':
                recent_my_d += 1
        if recent_my_d >= 2:
            return 'C'
        # Otherwise still cooperate to encourage mutual cooperation.
        return 'C'

    # If opponent just defected:
    if last_opp == 'D':
        # If we just cooperated and got exploited, retaliate.
        if last_my == 'C':
            # But if opponent is usually cooperative, forgive once in a while
            if opp_def_rate < 0.2 and n >= 12 and opp_d_streak < 2:
                if rng.random() < 0.4:
                    return 'C'
            return 'D'
        # Both defected (DD loop): try to break it if opponent has been mostly cooperative.
        if last_my == 'D':
            if opp_def_rate < 0.3:
                # Weaker opponent tendency to defect -> offer peace
                if opp_d_streak >= 2:
                    # Long DD loop, definitely try cooperation
                    return 'C'
                if rng.random() < 0.25:
                    return 'C'
            elif opp_def_rate < 0.6:
                if opp_d_streak >= 3:
                    return 'C'
                if rng.random() < 0.1:
                    return 'C'
            else:
                # Hard opponent, occasional peace offer to avoid lock-in
                if opp_d_streak >= 4 and rng.random() < 0.15:
                    return 'C'
            return 'D'

    # Opponent cooperated and we cooperated last round (CC):
    if last_opp == 'C' and last_my == 'C':
        # If opponent has never defected in last 10, occasionally probe late
        if n >= 10 and opp_def_rate < 0.15:
            # Rare probe to detect exploiters; low frequency to preserve CC.
            if rng.random() < 0.04:
                return 'D'
        return 'C'

    # Fallback
    return 'C'
